<?php
require __DIR__.'/bootstrap.php';
requireAuth();

$canEdit=canManageCatalog();$error='';$notice='';$items=[];$product=null;$collections=[];$pdo=null;
function productSlug(string $name):string{$s=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name);if($s===false)$s=$name;$s=strtolower($s);$s=preg_replace('/[^a-z0-9]+/','-',$s);$s=trim((string)$s,'-');return substr($s!==''?$s:'producto',0,130);}
function positiveInt($v,int $max=999999999999):int{$s=trim((string)$v);if(!preg_match('/^\d+$/',$s))throw new RuntimeException('Ingresá un número válido.');$n=(int)$s;if($n<0||$n>$max)throw new RuntimeException('Valor fuera de rango.');return $n;}
function assertProductReady(PDO $pdo,int $id):void{
 $q=$pdo->prepare("SELECT p.base_price,
 (SELECT COUNT(*) FROM product_collections pc JOIN collections c ON c.id=pc.collection_id WHERE pc.product_id=p.id AND c.is_active=1) collections_ok,
 (SELECT COUNT(*) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=1 AND (pv.availability_mode='bajo_pedido' OR pv.stock_qty>0)) buyable_variants,
 (SELECT COUNT(*) FROM product_images pi WHERE pi.product_id=p.id) images_ok
 FROM products p WHERE p.id=?");$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('Producto no encontrado.');
 if((int)$r['base_price']<=0)throw new RuntimeException('No podés publicar un producto sin precio válido.');
 if(!(int)$r['collections_ok'])throw new RuntimeException('No podés publicar un producto sin una colección activa.');
 if(!(int)$r['buyable_variants'])throw new RuntimeException('No podés publicar un producto sin al menos una variante disponible.');
 if(!(int)$r['images_ok'])throw new RuntimeException('No podés publicar un producto sin al menos una imagen.');
}

try{
 $pdo=db();$collections=$pdo->query("SELECT id,name FROM collections WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!$canEdit){http_response_code(403);throw new RuntimeException('Tu usuario no tiene permiso para modificar productos.');}
  if(!validCsrf()){http_response_code(403);throw new RuntimeException('La sesión venció. Recargá la página.');}
  $action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
  if($action==='save'){
   $name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$description=trim((string)($_POST['description']??''));$price=positiveInt($_POST['base_price']??0);$featured=isset($_POST['featured'])?1:0;$type=(string)($_POST['product_type']??'remera');$audience=(string)($_POST['audience']??'Unisex');$fit=(string)($_POST['fit']??'');$collectionId=filter_var($_POST['collection_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
   if($name===''||mb_strlen($name)>200)throw new RuntimeException('El nombre es obligatorio (máximo 200 caracteres).');if(mb_strlen($sku)>80)throw new RuntimeException('El SKU supera 80 caracteres.');if(!in_array($type,['remera','kepi'],true))throw new RuntimeException('Tipo no válido.');if(!in_array($audience,['Mujer','Hombre','Unisex'],true))throw new RuntimeException('Público no válido.');if(!in_array($fit,['','Regular','Oversize','Cropped','Único'],true))throw new RuntimeException('Fit no válido.');if(!$collectionId)throw new RuntimeException('Seleccioná una colección.');
   $q=$pdo->prepare('SELECT COUNT(*) FROM collections WHERE id=? AND is_active=1');$q->execute([$collectionId]);if(!(int)$q->fetchColumn())throw new RuntimeException('La colección seleccionada no está disponible.');
   $pdo->beginTransaction();
   if($id){$q=$pdo->prepare('UPDATE products SET name=?,sku=?,description=?,base_price=?,featured=?,product_type=?,audience=?,fit=? WHERE id=?');$q->execute([$name,$sku!==''?$sku:null,$description!==''?$description:null,$price,$featured,$type,$audience,$fit,$id]);$actionName='product.update';}
   else{$slugBase=productSlug($name);$slug=$slugBase;$n=2;$check=$pdo->prepare('SELECT COUNT(*) FROM products WHERE slug=?');do{$check->execute([$slug]);if(!(int)$check->fetchColumn())break;$suffix='-'.$n++;$slug=substr($slugBase,0,160-strlen($suffix)).$suffix;}while($n<1000);$q=$pdo->prepare("INSERT INTO products (sku,slug,name,description,base_price,currency,status,featured,product_type,audience,fit) VALUES (?,?,?,?,?,'PYG','draft',?,?,?,?)");$q->execute([$sku!==''?$sku:null,$slug,$name,$description!==''?$description:null,$price,$featured,$type,$audience,$fit]);$id=(int)$pdo->lastInsertId();$actionName='product.create';}
   $pdo->prepare('DELETE FROM product_collections WHERE product_id=?')->execute([$id]);$pdo->prepare('INSERT INTO product_collections (product_id,collection_id,sort_order) VALUES (?,?,0)')->execute([$id,$collectionId]);$pdo->commit();auditLog($pdo,$actionName,'product',(int)$id);header('Location: /admin/products.php?edit='.(int)$id.'&saved=1',true,303);exit;
  }
  if($action==='status'){
   if(!$id)throw new RuntimeException('Producto no válido.');$status=(string)($_POST['status']??'');if(!in_array($status,['draft','active','archived'],true))throw new RuntimeException('Estado no válido.');if($status==='active')assertProductReady($pdo,(int)$id);$pdo->prepare('UPDATE products SET status=? WHERE id=?')->execute([$status,$id]);auditLog($pdo,'product.status.'.$status,'product',(int)$id);header('Location: /admin/products.php?saved=1',true,303);exit;
  }
  throw new RuntimeException('Acción no válida.');
 }
 $editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($editId){$q=$pdo->prepare("SELECT p.*, (SELECT pc.collection_id FROM product_collections pc WHERE pc.product_id=p.id ORDER BY pc.sort_order,pc.collection_id LIMIT 1) collection_id FROM products p WHERE p.id=?");$q->execute([$editId]);$product=$q->fetch();if(!$product)throw new RuntimeException('No se encontró el producto.');}
 $search=trim((string)($_GET['q']??''));if(mb_strlen($search)>100)$search=mb_substr($search,0,100);
 $sql="SELECT p.id,p.sku,p.name,p.base_price,p.status,p.product_type,p.audience,p.updated_at,(SELECT c.name FROM product_collections pc JOIN collections c ON c.id=pc.collection_id WHERE pc.product_id=p.id ORDER BY pc.sort_order,c.sort_order LIMIT 1) collection_name,(SELECT COUNT(*) FROM product_variants pv WHERE pv.product_id=p.id) variant_count,(SELECT COUNT(*) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=1 AND (pv.availability_mode='bajo_pedido' OR pv.stock_qty>0)) buyable_count,(SELECT COUNT(*) FROM product_images pi WHERE pi.product_id=p.id) image_count FROM products p";
 if($search!==''){$q=$pdo->prepare($sql.' WHERE p.name LIKE ? OR p.sku LIKE ? ORDER BY p.id DESC LIMIT 100');$q->execute(['%'.$search.'%','%'.$search.'%']);$items=$q->fetchAll();}else{$items=$pdo->query($sql.' ORDER BY p.id DESC LIMIT 100')->fetchAll();}
 if(isset($_GET['saved']))$notice='Cambios guardados correctamente.';
}catch(Throwable $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();error_log('InYou productos: '.$e->getMessage());$error=$e instanceof PDOException?'No se pudo completar la operación en MySQL.':$e->getMessage();}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Productos · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.wrap{max-width:1250px;margin:auto}.toolbar,.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.toolbar{justify-content:space-between;margin:24px 0}.btn{background:#202321;color:#fff;border:0;border-radius:7px;padding:11px 16px;text-decoration:none}.btn.secondary{background:#fff;color:#222;border:1px solid #d9d8d3}.input,.textarea,.select{width:100%;padding:11px;border:1px solid #d9d8d3;border-radius:7px;background:#fff}.textarea{min-height:110px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel{background:#fff;border:1px solid #e7e5df;border-radius:12px;padding:22px;margin:20px 0}.table{width:100%;border-collapse:collapse}.table td,.table th{padding:11px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}.field{display:block;margin-bottom:12px}.field span{display:block;margin-bottom:6px;font-weight:600}.alert{padding:12px;border-radius:8px;background:#e4f2e9}.error{background:#f9e6e4}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#f1f0eb;font-size:12px}.muted{color:#777}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style></head><body class="dashboard"><aside class="sidebar"><div class="brand">in<span>You</span><i>.</i></div><div class="eyebrow">PANEL ADMINISTRATIVO</div><nav><a href="/admin/">Resumen</a><a class="selected" href="/admin/products.php">Productos</a><a href="/admin/collections.php">Colecciones</a></nav></aside><main class="content"><div class="wrap"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?></div><form method="post" action="/admin/logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="signout">Cerrar sesión</button></form></header><div class="eyebrow">CATÁLOGO</div><h1>Productos</h1><p>Producto + colección + variantes + stock + imágenes.</p><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if($notice):?><div class="alert"><?=h($notice)?></div><?php endif;?><div class="toolbar"><form method="get" style="display:flex;gap:8px;flex:1;max-width:500px"><input class="input" name="q" placeholder="Buscar por nombre o SKU" value="<?=h((string)($_GET['q']??''))?>"><button class="btn secondary">Buscar</button></form><?php if($canEdit):?><a class="btn" href="/admin/products.php?new=1">+ Nuevo producto</a><?php endif;?></div>
<?php if($canEdit&&(isset($_GET['new'])||$product)):?><section class="panel"><h2><?=$product?'Editar producto':'Nuevo producto'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h((string)($product['id']??''))?>"><div class="grid"><label class="field"><span>Nombre *</span><input class="input" name="name" maxlength="200" required value="<?=h((string)($product['name']??''))?>"></label><label class="field"><span>SKU base</span><input class="input" name="sku" maxlength="80" value="<?=h((string)($product['sku']??''))?>"></label></div><label class="field"><span>Descripción</span><textarea class="textarea" name="description"><?=h((string)($product['description']??''))?></textarea></label><div class="grid"><label class="field"><span>Precio base (Gs.) *</span><input class="input" name="base_price" type="number" min="0" required value="<?=h((string)($product['base_price']??0))?>"></label><label class="field"><span>Colección *</span><select class="select" name="collection_id" required><option value="">Seleccionar</option><?php foreach($collections as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($product['collection_id']??0)===(int)$c['id'])?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label class="field"><span>Tipo</span><select class="select" name="product_type"><option value="remera" <?=($product['product_type']??'remera')==='remera'?'selected':''?>>Remera</option><option value="kepi" <?=($product['product_type']??'')==='kepi'?'selected':''?>>Kepi</option></select></label><label class="field"><span>Público</span><select class="select" name="audience"><?php foreach(['Mujer','Hombre','Unisex'] as $v):?><option <?=$v===($product['audience']??'Unisex')?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><label class="field"><span>Fit</span><select class="select" name="fit"><?php foreach(['','Regular','Oversize','Cropped','Único'] as $v):?><option value="<?=h($v)?>" <?=$v===($product['fit']??'')?'selected':''?>><?=h($v===''?'Sin definir':$v)?></option><?php endforeach;?></select></label><label class="field"><span>Destacado</span><input type="checkbox" name="featured" value="1" <?=!empty($product['featured'])?'checked':''?>> Mostrar como destacado</label></div><div class="actions"><button class="btn">Guardar producto</button><a class="btn secondary" href="/admin/products.php">Cancelar</a><?php if($product):?><a class="btn secondary" href="/admin/variants.php?product=<?=(int)$product['id']?>">Variantes</a><a class="btn secondary" href="/admin/images.php?product=<?=(int)$product['id']?>">Imágenes</a><?php endif;?></div></form></section><?php endif;?>
<section class="panel"><h2>Listado</h2><div style="overflow:auto"><table class="table"><thead><tr><th>Producto</th><th>Colección</th><th>Precio</th><th>Preparación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=h($i['name'])?></strong><br><small><?=h((string)($i['sku']??'—'))?> · <?=h($i['product_type'])?> · <?=h($i['audience'])?></small></td><td><?=h((string)($i['collection_name']??'Sin colección'))?></td><td>Gs. <?=h(number_format((float)$i['base_price'],0,',','.'))?></td><td><span class="badge"><?=(int)$i['variant_count']?> variantes</span> <span class="badge"><?=(int)$i['buyable_count']?> disponibles</span> <span class="badge"><?=(int)$i['image_count']?> imágenes</span></td><td><?=h($i['status'])?></td><td><?php if($canEdit):?><div class="actions"><a href="/admin/products.php?edit=<?=(int)$i['id']?>">Editar</a><a href="/admin/variants.php?product=<?=(int)$i['id']?>">Stock</a><a href="/admin/images.php?product=<?=(int)$i['id']?>">Imágenes</a><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$i['id']?>"><select name="status"><option value="draft" <?=$i['status']==='draft'?'selected':''?>>Borrador</option><option value="active" <?=$i['status']==='active'?'selected':''?>>Publicado</option><option value="archived" <?=$i['status']==='archived'?'selected':''?>>Archivado</option></select><button class="btn secondary">Aplicar</button></form></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6">Todavía no hay productos.</td></tr><?php endif;?></tbody></table></div></section></div></main></body></html>